import { test, expect } from '@playwright/test';

test.describe('401 Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/protected-route');
  });

  test('should redirect to login on 401 error', async ({ page }) => {
    // Simulate a 401 error response
    await page.route('**/protected-route', (route) => {
      route.fulfill({
        status: 401,
        body: JSON.stringify({ message: 'Unauthorized' }),
      });
    });

    await page.goto('/protected-route');
    await expect(page.getByRole('heading', { name: /login/i })).toBeVisible();
  });

  test('should display login form after redirection', async ({ page }) => {
    // Simulate a 401 error response
    await page.route('**/protected-route', (route) => {
      route.fulfill({
        status: 401,
        body: JSON.stringify({ message: 'Unauthorized' }),
      });
    });

    await page.goto('/protected-route');
    await expect(page.getByLabel('Username')).toBeVisible();
    await expect(page.getByLabel('Password')).toBeVisible();
  });
});
